// Marstek Capacity Monitor: battery card, overview card and dashboard.
// Loaded by the integration itself; no button-card and no resources needed.
// GENERATED by scripts/build_card.py from dashboard/button-card/marstek_capacity_templates.yaml
// (the card logic) and scripts/card_glue.js (this frame). Do not edit by hand.

const MC_VERSION = "0.4.0";
const MC_DOMAIN = "marstek_capacity_monitor";
const MC_DOCS = "https://github.com/satscan1/marstek-capacity-monitor/blob/main/docs";

// Names come from the device registry and the card config: escape them.
function mcEsc(text) {
  return String(text).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
}

// The sensors a card reads (fixed list, so no scanning of all states).
const MC_KEYS = ["measured_capacity", "capacity_pct", "expected_capacity", "warranty_status",
  "warranty_end", "margin", "last_full_discharge", "last_full_charge", "monitor_status", "cell_spread"];

// Batteries of this integration, found through the entity registry.
// Cached per registry object: HA replaces it only when the registry changes.
let mcCache = { entities: null, devices: null, list: [] };
function mcBatteries(hass) {
  if (!hass) return [];
  if (mcCache.entities === hass.entities && mcCache.devices === hass.devices) return mcCache.list;
  const out = [];
  for (const [eid, ent] of Object.entries((hass && hass.entities) || {})) {
    if (ent.platform !== MC_DOMAIN) continue;
    const m = /^sensor\.marstek_(.+)_monitor_status$/.exec(eid);
    if (!m) continue;
    const dev = ent.device_id && hass.devices ? hass.devices[ent.device_id] : null;
    out.push({ id: m[1], name: (dev && (dev.name_by_user || dev.name)) || m[1].toUpperCase() });
  }
  out.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
  mcCache = { entities: hass.entities, devices: hass.devices, list: out };
  return out;
}

function mcLang(hass, config) {
  if (config && config.lang) return config.lang;
  const l = (hass && ((hass.locale && hass.locale.language) || hass.language)) || "en";
  return l.startsWith("nl") ? "nl" : l.startsWith("de") ? "de" : "en";
}

function batteryBody(states, variables, ctx) {
  const id = variables.battery;
  const nl = variables.lang === 'nl';
  const T = variables.lang === 'de' ? {
    title: 'Kapazität', nominal: 'Nennwert', usable: 'Nutzbar', measured: 'Gemessen',
    ofnew: 'noch verfügbar', expected: 'Herstellerangabe', spec: 'Herstellerangabe bei', margin: 'Abstand', floor: 'an Marstek melden',
    age: 'Jahre', cycles: 'Zyklen', trend: 'Trend', exp: 'Herst.',
    until: 'Garantie bis', n: 'Messungen', lastDis: 'letzte vollständige Entladung', lastChg: 'letzte vollständige Ladung', loc: 'de-DE',
    none: 'Noch keine vollständige Entladung gemessen (≥ 95 % → ≤ 15 %). Das kann im Winter eine Weile dauern.',
    missing: 'Sensor nicht gefunden:',
    status: {good: 'Gut', attention: 'Unter Herstellerangabe', critical: 'An Marstek melden (App)', no_measurement: 'Sammelt Daten'},
    collecting: 'sammelt Daten',
    mon: {
      measuring: n => `Messung läuft · ${n} vollständige Entladung${n === 1 ? '' : 'en'} gemessen`,
      collecting: 'Messung läuft · sammelt Daten für die erste Messung',
      no_recent_data: m => `Keine neuen Daten seit ${m} min · Verbindung zur Batterie prüfen`,
      sensor_missing: e => `Sensor nicht verfügbar: ${e}`,
      waiting_full_charge: s => `Nächster Schritt: auf 95 % oder mehr voll laden (jetzt ${s} %)`,
      ready: s => `Batterie voll (${s} %): eine Entladung auf 15 % oder weniger ergibt eine Messung`,
      full_discharge_running: (f, s) => `Vollständige Entladung läuft: von ${f} % auf jetzt ${s} %, Messung bei 15 % oder weniger`,
      interrupted: 'letzte Entladung zählte nicht (unterbrochen)'
    },
    chart: 'Diagramm', win3: 'jüngste 3 Jahre der Garantiezeit', chartTitle: 'Noch verfügbar pro Monat (%)', noData: 'Noch keine Messungen in diesem Zeitraum. Das Diagramm füllt sich nach der ersten vollständigen Entladung.',
    legCap: 'gemessen', legSpec: 'erwartet laut Hersteller', legRed: 'an Marstek melden',
    how: '<b>Wie liest man das?</b> Jeder Punkt ist ein Monat: wie viel Prozent der nutzbaren Kapazität damals noch vorhanden war. Die graue gestrichelte Linie zeigt, was der Hersteller in diesem Alter erwartet. Achte vor allem darauf, dass die Punkte nahe an oder über dieser Linie bleiben; ein langsamer Rückgang ist normal. Sinken sie in Richtung der roten Linie, melde es an Marstek.',
    cell: {title: 'Zellspannungsdifferenz nach Vollladung', none: 'Noch keine Messung: folgt nach der nächsten Vollladung, sobald die Batterie 5 Minuten geruht hat.', note: 'Differenz zwischen höchster und niedrigster Zelle, gemessen in Ruhe bei voller Batterie. Ohne Farbe: Marstek nennt keinen Normalwert.', last: 'zuletzt'},
    reason: (eol, life) => `Herstellerangabe: ${eol} % nach ${life} Zyklen (keine Garantie). Grün bis 5 Punkte darunter, orange noch tiefer, rot bei 75 % oder weniger.`
  } : nl ? {
    title: 'Capaciteit', nominal: 'Opgegeven', usable: 'Bruikbaar', measured: 'Gemeten',
    ofnew: 'nog beschikbaar', expected: 'Specificatie', spec: 'Specificatie fabrikant bij', margin: 'marge', floor: 'melden bij Marstek',
    age: 'jaar', cycles: 'cycli', trend: 'Trend', exp: 'spec.',
    until: 'garantie t/m', n: 'metingen', lastDis: 'laatste volle ontlading', lastChg: 'laatste volle lading', loc: 'nl-NL',
    none: 'Nog geen volledige ontlading gemeten (≥95% → ≤15%). Dat kan in de winter even duren.',
    missing: 'Sensor niet gevonden:',
    status: {good: 'Goed', attention: 'Onder specificatie', critical: 'Melden bij Marstek (app)', no_measurement: 'Verzamelt data'},
    collecting: 'verzamelt data',
    mon: {
      measuring: n => `Meting werkt · ${n} volledige ontlading${n === 1 ? '' : 'en'} gemeten`,
      collecting: 'Meting werkt · verzamelt data voor de eerste meting',
      no_recent_data: m => `Geen nieuwe gegevens sinds ${m} min · controleer de koppeling van de batterij`,
      sensor_missing: e => `Sensor niet beschikbaar: ${e}`,
      waiting_full_charge: s => `Volgende stap: volledig laden tot 95 % of meer (nu ${s} %)`,
      ready: s => `Batterij vol (${s} %): een ontlading tot 15 % of lager geeft een meting`,
      full_discharge_running: (f, s) => `Volledige ontlading bezig: van ${f} % naar nu ${s} %, meting bij 15 % of lager`,
      interrupted: 'vorige ontlading telde niet mee (onderbroken)'
    },
    chart: 'Grafiek', win3: 'recente 3 jaar van garantieperiode', chartTitle: 'Nog beschikbaar per maand (%)', noData: 'Nog geen metingen in deze periode. De grafiek vult zich na de eerste volledige ontlading.',
    legCap: 'gemeten', legSpec: 'verwacht volgens fabrikant', legRed: 'melden bij Marstek',
    how: '<b>Hoe lees je dit?</b> Elke stip is een maand: hoeveel procent van de bruikbare capaciteit er toen nog was. De grijze stippellijn is wat de fabrikant op die leeftijd verwacht. Kijk vooral of de stippen dicht bij of boven die lijn blijven; langzaam dalen is normaal. Zakken ze richting de rode lijn, meld het dan bij Marstek.',
    cell: {title: 'Celverschil na volle lading', none: 'Nog geen meting: volgt na de volgende volle lading, als de batterij 5 minuten in rust is.', note: 'Verschil tussen hoogste en laagste cel, gemeten in rust bij een volle batterij. Zonder kleur: Marstek geeft geen normaalwaarde.', last: 'laatste'},
    reason: (eol, life) => `Specificatie fabrikant: ${eol} % na ${life} cycli (geen garantie). Groen tot 5 punten eronder, oranje daaronder, rood bij 75 % en lager.`
  } : {
    title: 'Capacity', nominal: 'Rated', usable: 'Usable', measured: 'Measured',
    ofnew: 'remaining', expected: 'Spec', spec: 'Manufacturer spec at', margin: 'margin', floor: 'report to Marstek',
    age: 'yr', cycles: 'cycles', trend: 'Trend', exp: 'spec',
    until: 'warranty until', n: 'measurements', lastDis: 'last full discharge', lastChg: 'last full charge', loc: 'en-GB',
    none: 'No full discharge measured yet (≥95% → ≤15%). This can take a while in winter.',
    missing: 'Sensor not found:',
    status: {good: 'Good', attention: 'Below spec', critical: 'Report to Marstek (app)', no_measurement: 'Collecting data'},
    collecting: 'collecting data',
    mon: {
      measuring: n => `Monitor working · ${n} full discharge${n === 1 ? '' : 's'} measured`,
      collecting: 'Monitor working · collecting data for the first measurement',
      no_recent_data: m => `No new data for ${m} min · check the battery connection`,
      sensor_missing: e => `Sensor unavailable: ${e}`,
      waiting_full_charge: s => `Next step: charge fully to 95 % or more (now ${s} %)`,
      ready: s => `Battery full (${s} %): a discharge to 15 % or lower gives a measurement`,
      full_discharge_running: (f, s) => `Full discharge running: from ${f} % to now ${s} %, measured at 15 % or lower`,
      interrupted: 'last discharge did not count (interrupted)'
    },
    chart: 'Chart', win3: 'recent 3 years of warranty', chartTitle: 'Remaining per month (%)', noData: 'No measurements in this period yet. The chart fills after the first full discharge.',
    legCap: 'measured', legSpec: 'expected by manufacturer', legRed: 'report to Marstek',
    how: '<b>How to read this?</b> Each dot is one month: how much of the usable capacity was left. The grey dashed line is what the manufacturer expects at that age. Mainly check that the dots stay close to or above that line; a slow decline is normal. If they sink towards the red line, report it to Marstek.',
    cell: {title: 'Cell spread after full charge', none: 'No measurement yet: follows after the next full charge, once the battery has rested for 5 minutes.', note: 'Difference between the highest and lowest cell, measured at rest with a full battery. No colours: Marstek gives no normal value.', last: 'last'},
    reason: (eol, life) => `Manufacturer spec: ${eol} % after ${life} cycles (not a warranty). Green up to 5 points below, orange below that, red at 75 % or lower.`
  };
  // variables.demo (optional): fake states for a demo/gallery, nothing is written to HA
  const S = variables.demo ? {...states, ...variables.demo} : states;
  const g = k => S[`sensor.marstek_${id}_${k}`];
  const m = g('measured_capacity'), p = g('capacity_pct'), e = g('expected_capacity');
  const st = g('warranty_status'), we = g('warranty_end'), mg = g('margin');
  if (!m || !p || !e) return `<span style="color:#ef5350">${T.missing} sensor.marstek_${id}_…</span>`;
  const f = (v, d = 2) => (v === null || v === undefined || v === '' || isNaN(v)) ? '–'
    : Number(v).toLocaleString(T.loc, {minimumFractionDigits: d, maximumFractionDigits: d});
  const a = m.attributes, ea = e.attributes;
  const meas = parseFloat(m.state), pct = parseFloat(p.state), exp = parseFloat(e.state);
  const floor = p.attributes.red_pct ?? 75, tol = p.attributes.tolerance_pct ?? 5;
  const col = (v, x = exp) => isNaN(v) ? '#9aa0a6' : v <= floor ? '#ef5350' : v >= x - tol ? '#66bb6a' : '#ffa726';
  const name = variables.name || id.toUpperCase();
  const status = st ? (T.status[st.state] || st.state) : '';
  const muted = 'color:#9aa0a6';

  // Three capacities, strictly apart
  const box = (lbl, val, sub, c) => `
    <div style="flex:1;background:#262a33;border-radius:8px;padding:8px 10px">
      <div style="font-size:11px;${muted}">${lbl}</div>
      <div style="font-size:18px;font-weight:600;color:${c}">${val}</div>
      <div style="font-size:11px;${muted}">${sub}</div></div>`;
  const boxes = `<div style="display:flex;gap:8px;margin:10px 0">
    ${box(T.nominal, f(a.nominal_kwh) + ' kWh', '100 %', '#e8eaed')}
    ${box(T.usable, f(a.usable_kwh) + ' kWh', '− ' + f(a.reserve_kwh) + ' kWh', '#42a5f5')}
    ${box(T.measured, isNaN(meas) ? `<span style="font-size:13px;font-weight:400;${muted}">${T.collecting}</span>` : f(meas) + ' kWh', isNaN(pct) ? '' : f(pct, 1) + ' % ' + T.ofnew, col(pct))}
  </div>`;

  // Bar: measured vs expected vs warranty floor (0-100 % of usable)
  const bar = `<div style="position:relative;height:10px;background:#333744;border-radius:5px;margin:14px 0 4px">
      <div style="position:absolute;left:0;top:0;bottom:0;width:${isNaN(pct) ? 0 : Math.min(pct, 100)}%;background:${col(pct)};border-radius:5px"></div>
      <div title="${T.expected}" style="position:absolute;top:-4px;bottom:-4px;left:${exp}%;width:2px;background:#e8eaed"></div>
      <div title="${T.floor}" style="position:absolute;top:-4px;bottom:-4px;left:${floor}%;width:2px;background:#ef5350"></div>
    </div>
    <div style="display:flex;justify-content:space-between;font-size:11px;${muted}">
      <span><span style="color:#ef5350">▎</span>${T.floor} ${f(floor, 0)} %</span>
      <span><span style="color:#e8eaed">▎</span>${T.expected} ${f(exp, 1)} %</span>
    </div>`;

  const expLine = `<div style="margin-top:8px">${T.spec} ${f(ea.cycles, 0)} ${T.cycles}: <b>${f(ea.expected_kwh)} kWh</b>
      (${f(exp, 1)} %) · ${f(ea.age_years, 1)} ${T.age}
      ${mg && !isNaN(parseFloat(mg.state)) ? ` · ${T.margin} <b style="color:${col(pct)}">${parseFloat(mg.state) >= 0 ? '+' : ''}${f(mg.state)} kWh</b>` : ''}
      <div style="font-size:11px;${muted}">${T.reason(f(ea.cycle_eol_pct ?? 80, 0), f(ea.cycle_life ?? 6000, 0))}</div></div>`;

  // Monthly trend: trend column first, then newest -> oldest
  const tr = (a.trend || []).slice(0, variables.months || 6);
  let trend = g('monitor_status') ? '' : `<div style="margin-top:10px;font-size:12px;${muted}">${T.none}</div>`;
  if (tr.length) {
    // trend over the months shown: newest vs oldest
    const d = tr.length > 1 ? tr[0].pct - tr[tr.length - 1].pct : 0;
    const arrow = tr.length < 2 ? '·' : d > 1 ? '▲' : d < -1 ? '▼' : '▬';
    const ac = d < -1 ? col(pct) : '#9aa0a6';
    const mon = k => new Date(k + '-15').toLocaleString(T.loc, {month: 'short', year: '2-digit'});
    const cells = tr.map(t => `<td style="padding:2px 8px;text-align:right">
        <div style="font-size:11px;${muted}">${mon(t.month)}</div>
        <div style="font-weight:600;color:${col(t.pct, t.expected_pct)}">${f(t.pct, 0)}%</div>
        <div style="font-size:10px;${muted}">${T.exp} ${f(t.expected_pct, 0)}${t.temp_c != null ? ` · ${f(t.temp_c, 0)} °C` : ''}</div></td>`).join('');
    trend = `<table style="margin-top:10px;border-collapse:collapse;width:100%"><tr>
        <td style="padding:2px 8px 2px 0;${muted};font-size:11px;vertical-align:middle">${T.trend}<div style="font-size:18px;color:${ac}">${arrow}</div></td>
        ${cells}</tr></table>`;
  }

  const dt = k => { const e = g(k); return e && !['unknown', 'unavailable', ''].includes(e.state)
    ? new Date(e.state).toLocaleString(T.loc, {day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit'}) : '–'; };
  const foot = `<div style="margin-top:10px;font-size:11px;${muted}">
      ${T.lastDis} ${dt('last_full_discharge')} · ${T.lastChg} ${dt('last_full_charge')}<br>
      n=${a.measurement_count ?? 0} ${T.n}</div>`;

  // Is the monitor itself working? (status sensor)
  const ms = g('monitor_status');
  let monLine = '';
  if (ms) {
    const sa = ms.attributes, M = T.mon;
    const dotc = {measuring: '#66bb6a', collecting: '#42a5f5', no_recent_data: '#ffa726', sensor_missing: '#ef5350'}[ms.state] || '#9aa0a6';
    const main = ms.state === 'measuring' ? M.measuring(sa.full_discharges ?? 0)
      : ms.state === 'no_recent_data' ? M.no_recent_data(sa.last_data_minutes ?? '?')
      : ms.state === 'sensor_missing' ? M.sensor_missing((sa.missing || []).join(', '))
      : M.collecting;
    const soc = sa.soc ?? '–';
    const step = ['measuring', 'collecting'].includes(ms.state)
      ? (sa.phase === 'full_discharge_running' ? M.full_discharge_running(f(sa.from_soc, 0), soc)
        : sa.phase === 'ready' ? M.ready(soc) : M.waiting_full_charge(soc)) : '';
    const intr = sa.interrupted ? ` · ${M.interrupted}` : '';
    monLine = `<div style="margin-top:6px;font-size:12px"><span style="color:${dotc}">●</span> ${main}
      ${step ? `<div style="font-size:11px;${muted};margin-left:14px">${step}${intr}</div>` : ''}</div>`;
  }

  // Cell balance (only when cell sensors are configured)
  const cs = g('cell_spread');
  let cells = '';
  if (cs) {
    const ct = (cs.attributes.trend || []).slice(0, variables.months || 6);
    const C = T.cell;
    if (!ct.length) {
      cells = `<div style="margin-top:10px;font-size:12px"><b>${C.title}</b><div style="font-size:11px;${muted}">${C.none}</div></div>`;
    } else {
      const d = ct.length > 1 ? ct[0].spread_mv - ct[ct.length - 1].spread_mv : 0;
      const arrow = ct.length < 2 ? '·' : d > 2 ? '▲' : d < -2 ? '▼' : '▬';
      const mon2 = k => new Date(k + '-15').toLocaleString(T.loc, {month: 'short', year: '2-digit'});
      const cc = ct.map(t => `<td style="padding:2px 8px;text-align:right">
          <div style="font-size:11px;${muted}">${mon2(t.month)}</div>
          <div style="font-weight:600">${f(t.spread_mv, 0)} mV</div>
          <div style="font-size:10px;${muted}">n=${t.n}</div></td>`).join('');
      cells = `<div style="margin-top:10px;font-size:12px"><b>${C.title}</b> · ${C.last} ${f(cs.state, 0)} mV
        <table style="margin-top:4px;border-collapse:collapse;width:100%"><tr>
        <td style="padding:2px 8px 2px 0;${muted};font-size:11px;vertical-align:middle">${T.trend}<div style="font-size:18px">${arrow}</div></td>
        ${cc}</tr></table>
        <div style="font-size:11px;${muted}">${C.note}</div></div>`;
    }
  }

  // Chart, opened with the small button under the status (top right).
  // The chart shows the most recent 3 years (never before the installation date).
  const open = !!ctx.chart;
  const act = js => `data-mc="${js}"`;
  const chartBtn = `<div ${act('h._mcChart=!h._mcChart;')} style="margin-top:4px;display:inline-block;font-size:11px;padding:1px 8px;border:1px solid #333744;border-radius:10px;color:#9aa0a6;cursor:pointer;user-select:none;pointer-events:auto">${T.chart} ${open ? '▾' : '▸'}</div>`;
  let chart = '';
  if (open) {
    const km = k => { const [yy, mm] = k.split('-').map(Number); return yy * 12 + mm - 1; };
    const nd = new Date(), nowI = nd.getFullYear() * 12 + nd.getMonth();
    const startI = nowI - Math.round((ea.age_years ?? 0) * 12);
    const x0 = Math.max(startI, nowI - 35), x1 = nowI;
    const span = Math.max(1, x1 - x0);
    const pts = (a.trend || []).filter(t => km(t.month) >= x0 && km(t.month) <= x1).slice().reverse();
    // drawn in real pixels: the card is on screen once the button was pressed
    const W = Math.max(260, Math.round((ctx.width || 360) - 50)), H = 120, L = 28, R = 30, Tp = 10, B = 18;
    const lo = Math.min(70, Math.floor((Math.min(floor, ...pts.map(t => t.pct)) - 5) / 10) * 10);
    const hi = Math.max(100, Math.ceil(Math.max(0, ...pts.map(t => t.pct)) / 5) * 5);
    const X = i => L + (i - x0) * (W - L - R) / span;
    const Y = v => Tp + (hi - v) * (H - Tp - B) / (hi - lo);
    const dim = '#6f747b';
    let svg = '';
    for (let v = lo; v <= hi; v += 10)
      svg += `<line x1="${L}" x2="${W - R}" y1="${Y(v)}" y2="${Y(v)}" stroke="#2a2e37" stroke-width="1"/><text x="${L - 5}" y="${Y(v) + 3.5}" font-size="10" fill="${dim}" text-anchor="end">${v}</text>`;
    const y0 = Math.ceil(x0 / 12), y1 = Math.floor(x1 / 12), stepY = (y1 - y0) > 6 ? 2 : 1;
    for (let yy = y0; yy <= y1; yy += stepY) {
      if (yy * 12 < x0 || yy * 12 > x1) continue;
      svg += `<line x1="${X(yy * 12)}" x2="${X(yy * 12)}" y1="${H - B}" y2="${H - B + 4}" stroke="${dim}" stroke-width="1"/><text x="${X(yy * 12)}" y="${H - 3}" font-size="10" fill="${dim}" text-anchor="middle">${yy}</text>`;
    }
    svg += `<line x1="${L}" x2="${W - R}" y1="${Y(floor)}" y2="${Y(floor)}" stroke="#ef5350" stroke-opacity="0.55" stroke-width="1" stroke-dasharray="4 4"/><text x="${W - R + 3}" y="${Y(floor) + 3.5}" font-size="10" fill="#ef5350" fill-opacity="0.7">${f(floor, 0)}%</text>`;
    const sp = pts.map(t => [km(t.month), t.expected_pct]);
    if (!isNaN(exp) && (!sp.length || sp[sp.length - 1][0] < nowI)) sp.push([nowI, exp]);
    if (sp.length > 1) svg += `<polyline points="${sp.map(([i, v]) => `${X(i)},${Y(v)}`).join(' ')}" fill="none" stroke="#9aa0a6" stroke-opacity="0.7" stroke-width="1" stroke-dasharray="4 3"/>`;
    if (pts.length > 1) svg += `<polyline points="${pts.map(t => `${X(km(t.month))},${Y(t.pct)}`).join(' ')}" fill="none" stroke="#66bb6a" stroke-opacity="0.45" stroke-width="1.2"/>`;
    const monL = k => new Date(k + '-15').toLocaleString(T.loc, {month: 'short', year: 'numeric'});
    svg += pts.map(t => `<circle cx="${X(km(t.month))}" cy="${Y(t.pct)}" r="${pts.length > 40 ? 2.2 : 3}" fill="${col(t.pct, t.expected_pct)}"><title>${monL(t.month)}: ${f(t.pct, 1)} % (${T.legSpec} ${f(t.expected_pct, 0)} %${t.temp_c != null ? `, ${f(t.temp_c, 0)} °C` : ''})</title></circle>`).join('');
    if (pts.length) { const t = pts[pts.length - 1]; svg += `<text x="${X(km(t.month))}" y="${Y(t.pct) - 6}" font-size="10" fill="#e8eaed" text-anchor="middle">${f(t.pct, 0)}</text>`; }
    chart = `<div style="margin-top:8px;padding:8px 10px;background:#22262e;border-radius:8px">
        <div style="display:flex;flex-wrap:wrap;justify-content:space-between;column-gap:10px;font-size:11px;${muted}"><span>${T.chartTitle}</span><span>${T.win3}</span></div>
        ${pts.length ? `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="max-width:100%;height:auto;display:block;margin-top:4px">${svg}</svg>` : ''}
        ${pts.length ? '' : `<div style="font-size:11px;${muted};margin:4px 0">${T.noData}</div>`}
        <div style="font-size:10px;${muted};margin-top:2px"><span style="color:#66bb6a">●</span> ${T.legCap} · <span style="color:#9aa0a6">┄</span> ${T.legSpec} · <span style="color:#ef5350">┄</span> ${T.legRed}</div>
        <div style="font-size:11px;${muted};margin-top:6px;line-height:1.35">${T.how}</div>
      </div>`;
  }

  return `<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
      <span style="font-size:15px;font-weight:600">${name} · ${T.title}</span>
      <div style="text-align:right;flex-shrink:0"><div style="font-size:12px;color:${col(pct)}">${status}</div>${chartBtn}</div></div>
    ${chart}${monLine}${boxes}${bar}${expLine}${trend}${cells}${foot}`;
}

function overviewBody(states, variables) {
  const nl = variables.lang === 'nl';
  const T = variables.lang === 'de'
    ? {title: 'Kapazität Heimspeicher — % noch verfügbar pro Monat', bat: 'Batterie', trend: 'Trend', now: 'Jetzt', exp: 'Herstellerangabe', loc: 'de-DE', none: 'sammelt Daten', mon: {measuring: 'Messung läuft', collecting: 'sammelt Daten', no_recent_data: 'keine aktuellen Daten', sensor_missing: 'Sensor nicht verfügbar'}, legend: 'Grün: im Rahmen der Herstellerangabe (bis 5 Punkte darunter) · orange: unter Herstellerangabe · rot: 75 % oder weniger, über die Marstek-App melden. Kleine Zahl = Herstellerangabe für diesen Monat. ✓ Messung läuft · ⏳ sammelt Daten · ⚠ Verbindung prüfen.'}
    : nl
    ? {title: 'Capaciteit thuisbatterijen — % nog beschikbaar per maand', bat: 'Batterij', trend: 'Trend', now: 'Nu', exp: 'Specificatie', loc: 'nl-NL', none: 'verzamelt data', mon: {measuring: 'meting werkt', collecting: 'verzamelt data', no_recent_data: 'geen recente data', sensor_missing: 'sensor niet beschikbaar'}, legend: 'Groen: volgens specificatie fabrikant (tot 5 punten eronder) · oranje: onder specificatie · rood: 75 % of lager, melden via de Marstek-app. Klein getal = specificatie voor die maand. ✓ meting werkt · ⏳ verzamelt data · ⚠ controleer de koppeling.'}
    : {title: 'Home battery capacity — % remaining per month', bat: 'Battery', trend: 'Trend', now: 'Now', exp: 'Spec', loc: 'en-GB', none: 'collecting data', mon: {measuring: 'monitor working', collecting: 'collecting data', no_recent_data: 'no recent data', sensor_missing: 'sensor unavailable'}, legend: 'Green: within manufacturer spec (up to 5 points below) · orange: below spec · red: 75 % or lower, report via the Marstek app. Small number = spec for that month. ✓ monitor working · ⏳ collecting data · ⚠ check the connection.'};
  const f = (v, d = 0) => (v === null || v === undefined || isNaN(v)) ? '–'
    : Number(v).toLocaleString(T.loc, {minimumFractionDigits: d, maximumFractionDigits: d});
  const muted = 'color:#9aa0a6';
  const S = variables.demo ? {...states, ...variables.demo} : states;
  const list = (variables.batteries || []).slice(0, 6).map(b => typeof b === 'string' ? {id: b} : b);
  const rows = list.map(b => {
    const m = S[`sensor.marstek_${b.id}_measured_capacity`];
    const p = S[`sensor.marstek_${b.id}_capacity_pct`];
    const e = S[`sensor.marstek_${b.id}_expected_capacity`];
    const s = S[`sensor.marstek_${b.id}_monitor_status`];
    return {b, m, p, e, s, trend: m ? (m.attributes.trend || []) : []};
  });
  const months = [...new Set(rows.flatMap(r => r.trend.map(t => t.month)))]
    .sort().reverse().slice(0, variables.months || 6);
  const mon = k => new Date(k + '-15').toLocaleString(T.loc, {month: 'short', year: '2-digit'});
  const th = s => `<th style="padding:4px 10px;text-align:right;font-weight:400;font-size:11px;${muted}">${s}</th>`;
  const head = `<tr><th style="text-align:left;font-weight:400;font-size:11px;${muted}">${T.bat}</th>
      ${th(T.trend)}${th(T.now)}${months.map(k => th(mon(k))).join('')}${th(T.exp)}</tr>`;
  const body = rows.map(r => {
    const floor = r.p ? (r.p.attributes.red_pct ?? 75) : 75;
    const tol = r.p ? (r.p.attributes.tolerance_pct ?? 5) : 5;
    const expNow = r.e ? parseFloat(r.e.state) : NaN;
    const col = (v, x = expNow) => isNaN(v) ? '#9aa0a6' : v <= floor ? '#ef5350' : v >= x - tol ? '#66bb6a' : '#ffa726';
    const name = r.b.name || r.b.id.toUpperCase();
    if (!r.m) return `<tr><td colspan="${months.length + 4}" style="color:#ef5350">sensor.marstek_${r.b.id}_… ?</td></tr>`;
    const t = r.trend.filter(x => months.includes(x.month));
    const d = t.length > 1 ? t[0].pct - t[t.length - 1].pct : 0;
    const arrow = t.length < 2 ? '·' : d > 1 ? '▲' : d < -1 ? '▼' : '▬';
    const now = parseFloat(r.p.state);
    const cells = months.map(k => {
      const c = t.find(x => x.month === k);
      return c ? `<td style="padding:4px 10px;text-align:right"><span style="font-weight:600;color:${col(c.pct, c.expected_pct)}">${f(c.pct)}</span><span style="font-size:10px;${muted}"> /${f(c.expected_pct)}</span></td>`
               : `<td style="padding:4px 10px;text-align:right;${muted}">·</td>`;
    }).join('');
    return `<tr style="border-top:1px solid #333744">
        <td style="padding:4px 16px 4px 0;white-space:nowrap"><span style="color:${col(now)}">●</span> ${name}${r.s ? (() => {
          const sym = {measuring: ['✓', '#66bb6a'], collecting: ['⏳', '#42a5f5'], no_recent_data: ['⚠', '#ffa726'], sensor_missing: ['⚠', '#ef5350']}[r.s.state] || ['', ''];
          return ` <span title="${T.mon[r.s.state] || r.s.state}" style="font-size:11px;color:${sym[1]}">${sym[0]}</span>`; })() : ''}</td>
        <td style="padding:4px 10px;text-align:right;color:${d < -1 ? col(now) : '#9aa0a6'}">${arrow}</td>
        <td style="padding:4px 10px;text-align:right;font-weight:600;color:${col(now)}">${isNaN(now) ? `<span style="font-weight:400;font-size:11px;${muted}">${T.none}</span>` : f(now, 1) + '%'}</td>
        ${cells}
        <td style="padding:4px 10px;text-align:right;${muted}">${f(parseFloat(r.e.state), 1)}%</td></tr>`;
  }).join('');
  return `<div style="font-size:15px;font-weight:600;margin-bottom:8px">${T.title}</div>
    <div style="overflow-x:auto"><table style="border-collapse:collapse;width:auto;font-size:13px">${head}${body}</table></div>
    <div style="margin-top:8px;font-size:11px;${muted}">${T.legend}</div>`;
}

const MC_STYLE = `
  :host { display: block; height: 100%; }
  ha-card { background: #1e2128; border: 1px solid #333744; border-radius: 12px;
    padding: 14px; color: #e8eaed; font-size: 13px; height: 100%; box-sizing: border-box;
    text-align: left; white-space: normal; }
  [data-mc] { cursor: pointer; }
`;

class MarstekCapacityBase extends HTMLElement {
  setConfig(config) {
    this._config = { ...(config || {}) };
    this._sig = null;
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    const sig = this._signature();
    if (sig !== this._sig) {
      this._sig = sig;
      this._render();
    }
  }

  get hass() {
    return this._hass;
  }

  // Only redraw when one of our own sensors changed (HA replaces a state
  // object on every change, so comparing the objects is cheap).
  _signature() {
    if (!this._hass) return "";
    const ids = this._ids();
    const objs = [];
    for (const id of ids) for (const k of MC_KEYS) objs.push(this._hass.states[`sensor.marstek_${id}_${k}`]);
    const same = this._lastObjs && this._lastObjs.length === objs.length
      && objs.every((o, i) => o === this._lastObjs[i]);
    if (!same) {
      this._lastObjs = objs;
      this._rev = (this._rev || 0) + 1;
    }
    return `${mcLang(this._hass, this._config)}|${ids.join(",")}|${this._rev}`;
  }

  _render() {
    if (!this._hass || !this._config) return;
    if (!this.shadowRoot) {
      this.attachShadow({ mode: "open" });
      this.shadowRoot.addEventListener("click", (ev) => {
        const el = ev.composedPath().find((n) => n.dataset && n.dataset.mc);
        if (!el) return;
        ev.stopPropagation();
        this._action(el.dataset.mc);
        this._render();
      });
    }
    let html;
    try {
      html = this._html();
    } catch (err) {
      html = `<span style="color:#ef5350">Marstek Capacity Monitor: ${mcEsc(err)}</span>`;
    }
    this.shadowRoot.innerHTML = `<style>${MC_STYLE}</style><ha-card>${html}</ha-card>`;
  }

  _action(_act) {}

  getCardSize() {
    return 6;
  }
}

class MarstekCapacityCard extends MarstekCapacityBase {
  static getStubConfig(hass) {
    const b = mcBatteries(hass)[0];
    return b ? { battery: b.id } : {};
  }

  _battery() {
    const found = mcBatteries(this._hass);
    const id = this._config.battery || (found[0] && found[0].id);
    const name = this._config.name || (found.find((b) => b.id === id) || {}).name;
    return { id: id && String(id).replace(/[^a-z0-9_]/gi, ""), name: name ? mcEsc(name) : name };
  }

  _ids() {
    const b = this._battery();
    return b.id ? [b.id] : [];
  }

  _action(act) {
    if (act.includes("_mcChart")) this._chart = !this._chart;
  }

  _html() {
    const b = this._battery();
    const lang = mcLang(this._hass, this._config);
    if (!b.id) {
      return {
        nl: "Nog geen batterij gevonden. Voeg er een toe via Instellingen → Apparaten en diensten → Voeg integratie toe → Marstek Capacity Monitor.",
        de: "Noch keine Batterie gefunden. Füge eine hinzu: Einstellungen → Geräte & Dienste → Integration hinzufügen → Marstek Capacity Monitor.",
      }[lang] || "No battery found yet. Add one via Settings → Devices & services → Add integration → Marstek Capacity Monitor.";
    }
    const variables = { battery: b.id, name: b.name, lang, months: this._config.months || 6, demo: this._config.demo };
    return batteryBody(this._hass.states, variables, { chart: this._chart, width: this.offsetWidth });
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6, rows: "auto" };
  }
}

class MarstekCapacityOverviewCard extends MarstekCapacityBase {
  static getStubConfig() {
    return {};
  }

  _list() {
    const found = mcBatteries(this._hass);
    const wanted = this._config.batteries;
    if (!wanted) return found.map((b) => ({ id: b.id, name: mcEsc(b.name) }));
    return wanted.map((x) => {
      const b = typeof x === "string" ? { id: x } : x;
      const name = b.name || (found.find((f) => f.id === b.id) || {}).name;
      return { id: String(b.id).replace(/[^a-z0-9_]/gi, ""), name: name ? mcEsc(name) : name };
    });
  }

  _ids() {
    return this._list().map((b) => b.id);
  }

  _html() {
    const lang = mcLang(this._hass, this._config);
    const list = this._list();
    if (!list.length) {
      return { nl: "Nog geen batterij gevonden.", de: "Noch keine Batterie gefunden." }[lang] || "No battery found yet.";
    }
    const months = this._config.months || (list.length <= 2 ? 3 : 6);
    return overviewBody(this._hass.states, { batteries: list, lang, months, demo: this._config.demo });
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6, rows: "auto" };
  }
}

