// Dashboard that arranges the cards for 1 to 6 batteries:
//   1-2: batteries a third each, the overview to the right (one row of three)
//   3-6: overview two thirds plus a free spot, then 3 / 2x2 / 3+2 / 3+3
class MarstekCapacityDashboardStrategy {
  static async generate(config, hass) {
    const T = MC_DASH_TEXT[mcLang(hass, config)] || MC_DASH_TEXT.en;
    const found = mcBatteries(hass).slice(0, 6);
    const n = found.length;
    const battery = (b, columns) => ({
      type: "custom:marstek-capacity-card", battery: b.id, name: b.name,
      grid_options: { columns, rows: "auto" },
    });
    const overview = (columns) => ({
      type: "custom:marstek-capacity-overview-card",
      grid_options: { columns, rows: "auto" },
    });
    let cards;
    if (n === 0) {
      cards = [{ type: "markdown", content: T.none }];
    } else if (n <= 2) {
      cards = [...found.map((b) => battery(b, 12)), overview(12)];
    } else {
      cards = [
        overview(24),
        { type: "markdown", grid_options: { columns: 12, rows: "auto" }, content: T.free },
        ...found.map((b) => battery(b, n === 4 ? 18 : 12)),
      ];
    }
    return {
      title: T.title,
      views: [{
        title: T.title,
        path: "marstek",
        type: "sections",
        max_columns: 3,
        sections: [{ type: "grid", column_span: 3, cards }],
      }],
    };
  }
}

if (!customElements.get("marstek-capacity-card")) {
  customElements.define("marstek-capacity-card", MarstekCapacityCard);
  customElements.define("marstek-capacity-overview-card", MarstekCapacityOverviewCard);
  customElements.define("ll-strategy-dashboard-marstek-capacity", class extends HTMLElement {
    static generate(config, hass) {
      return MarstekCapacityDashboardStrategy.generate(config, hass);
    }

    static getCreateSuggestions(hass) {
      const T = MC_DASH_TEXT[mcLang(hass, {})] || MC_DASH_TEXT.en;
      return { title: T.title, icon: "mdi:battery-heart-variant" };
    }

    static registryDependencies = ["entities", "devices"];
    static noEditor = true;
  });
  window.customCards = window.customCards || [];
  window.customCards.push(
    {
      type: "marstek-capacity-card",
      name: "Marstek capacity (battery)",
      description: "Measured capacity of one battery against the manufacturer spec, with chart.",
      preview: true,
      documentationURL: `${MC_DOCS}/06-dashboard-gallery.md`,
    },
    {
      type: "marstek-capacity-overview-card",
      name: "Marstek capacity (overview)",
      description: "All batteries per month, newest first.",
      preview: true,
      documentationURL: `${MC_DOCS}/06-dashboard-gallery.md`,
    },
  );
  window.customStrategies = window.customStrategies || [];
  window.customStrategies.push({
    type: "marstek-capacity",
    strategyType: "dashboard",
    name: "Marstek battery capacity",
    description: "Capacity of your Marstek batteries, arranged for 1 to 6 batteries.",
    documentationURL: `${MC_DOCS}/06-dashboard-gallery.md`,
  });
  console.info(`%c MARSTEK-CAPACITY-CARD %c ${MC_VERSION} `, "background:#42a5f5;color:#000", "");
}
